from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 3 , 1 \n", "b, -2, 0", "c,4, \t"]) == [
        {"id": "a", "day": 3, "converted": True},
        {"id": "b", "day": -2, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    assert parse_session_log([
        "", "\n", " \t\n", "# comment", "  \t# comment,with,commas",
        "a,1,1", "", "b,2,0", "  # trailing comment",
    ]) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
    ]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
@pytest.mark.parametrize("prefix", [[], ["", "  # comment", " \t", "valid,2,1"]])
def test_parse_session_log_errors_include_input_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_session_log(prefix + [bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "b", "day": 9, "converted": True},
        {"id": "a", "day": 2, "converted": False},
        {"id": "c", "day": 0, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "a", "day": 2, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[2], events[4], events[3]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_zero_filled_and_range_filtered():
    events = [
        {"day": 5, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": True},
        {"day": 2, "converted": True},
        {"day": 3, "converted": False},
        {"day": 3, "converted": None},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 4) == [2, 0, 1]
    assert daily_conversion_counts(events, 2, 2) == [2]
    assert daily_conversion_counts(events, 4, 2) == []


def test_daily_conversion_counts_empty_sessions():
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
    assert daily_conversion_counts([], 1, -1) == []
