from sales_dashboard.loader import dedupe_sessions, parse_session_log
from sales_dashboard.report import campaign_summary, top_converting_groups


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (5, 2), (20, 2)])
def test_campaign_summary_weighted_rounded_and_calendar_window(days, recent):
    groups = {
        "small": [{"day": 1, "converted": True}],
        "large": [
            {"day": 4, "converted": True},
            {"day": 5, "converted": None},
            {"day": 1, "converted": False},
            {"day": 2, "converted": False},
            {"day": 2, "converted": False},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (2, ["best", "a"]), (10, ["best", "a", "z", "zero"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "zero": [{"converted": False}],
        "empty": [],
        "a": [{"converted": True}, {"converted": False}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 3) == []


def test_log_to_summary():
    events = dedupe_sessions(parse_session_log([
        "# sessions", "a,1,1", "b,2,1", "", "a,3,0", "c,4,", "d,5,1",
    ]))
    assert campaign_summary({"campaign": events, "empty": []}, 3) == {
        "rate": 0.5, "recent": 1, "groups": 1,
    }
